#include <iostream>
#include <utility>
#include <vector>

int main() {
    using namespace std;
    int N, M;
    cin >> N >> M;
    vector<pair<int, int>> edges(M);
    for (auto&& [u, v] : edges) {
        cin >> u >> v;
        --u; // 0-indexed にしておく
        --v;
    }

    int ans = M;
    // 2^N 通りの塗り方を全部探索する
    for (int bit = 0; bit < 1 << N; ++bit) {
        int delete_count = 0;
        for (const auto& [u, v] : edges) { // それぞれの辺を見て
            if ((1 & (bit >> u)) == (1 & (bit >> v))) // 結んでいる頂点が同じ色で塗られていたら
                ++delete_count; // カウントを増やす
        }
        ans = min(ans, delete_count); // 全部の塗り方にわたる最小値が答え
    }
    cout << ans << endl;
    return 0;
}
